class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        vector<int> res = {-1, -1};
        int pos = 1;
        int first = -1, prevCritical = -1;
        int minDist = INT_MAX, maxDist = -1;

        ListNode* prev = head;
        head = head->next;

        while (head && head->next) {
            pos++;
            if ((head->val > prev->val && head->val > head->next->val) ||
                (head->val < prev->val && head->val < head->next->val)) {

                if (first == -1)
                    first = pos;

                if (prevCritical != -1)
                    minDist = min(minDist, pos - prevCritical);

                prevCritical = pos;
                maxDist = pos - first;
            }

            prev = head;
            head = head->next;
        }

        if (minDist != INT_MAX)
            res = {minDist, maxDist};

        return res;
    }
};

