            prefixSum += curr->val;
            seen[prefixSum] = curr;
            curr = curr->next;
        }

        prefixSum = 0;
        curr = dummy;
        while (curr) {
            prefixSum += curr->val;
            curr->next = seen[prefixSum]->next;
            curr = curr->next;
        }

