// Simple hashmap implementation using linked list chaining
struct MapNode* insert(struct MapNode* head, int key){
    struct MapNode* curr = head;
    while(curr){
        if(curr->key == key){ curr->val += 1; return head; }
        curr = curr->next;
    }
    struct MapNode* newNode = (struct MapNode*)malloc(sizeof(struct MapNode));
    newNode->key = key;
    newNode->val = 1;
    newNode->next = head;
    return newNode;
}

