class Solution:
    def getWinner(self, head, k):
        from collections import deque
        dq = deque()
        curr = head
        while curr:
            dq.append(curr.val)
            curr = curr.next
        win = dq.popleft()
        count = 0
        while count < k:
            challenger = dq.popleft()
            if win > challenger:
                count += 1
                dq.append(challenger)
            else:
                dq.append(win)
                win = challenger
                count = 1
        return win

