        while(head != null){ q.add(head.val); head = head.next; }
        int win = q.poll();
        int count = 0;
        while(count < k){
            int challenger = q.poll();
            if(win > challenger){ count++; q.add(challenger); }
            else{ q.add(win); win = challenger; count = 1; }
        }
