struct Node* copyRandomList(struct Node* head){
    if(!head) return NULL;
    struct Node* nodes[1000]; // assuming max 1000 nodes
    struct Node* newNodes[1000];
    int n=0;
    struct Node* curr = head;
    while(curr){ nodes[n] = curr; newNodes[n] = (struct Node*)malloc(sizeof(struct Node)); newNodes[n]->val = curr->val; newNodes[n]->next=NULL; newNodes[n]->random=NULL; n++; curr = curr->next; }
    for(int i=0;i<n;i++){
        if(i<n-1) newNodes[i]->next = newNodes[i+1];
        if(nodes[i]->random){
            for(int j=0;j<n;j++){
                if(nodes[i]->random == nodes[j]){ newNodes[i]->random = newNodes[j]; break; }
            }
        }
    }
    return newNodes[0];
}

