        std::unordered_map<Node*, Node*> m;
        Node* curr = head;
        while (curr) {
            m[curr] = new Node(curr->val);
            curr = curr->next;
        }
        curr = head;
        while (curr) {
            m[curr]->next = m[curr->next];
            m[curr]->random = m[curr->random];
            curr = curr->next;
        }
        return m[head];
    }
};

class Solution:
    def flatten(self, head):
        if not head: return None
        stack = [head]
        prev = None
        while stack:
            node = stack.pop()
            if prev: prev.next = node; node.prev = prev
            if node.next: stack.append(node.next)
            if node.child: stack.append(node.child); node.child = None
            prev = node
        return head

class Solution {
    public Node flatten(Node head){
        if(head == null) return null;
        Deque<Node> stack = new ArrayDeque<>();
        stack.push(head);
        Node prev = null;
        while(!stack.isEmpty()){
            Node node = stack.pop();
            if(prev != null){ prev.next = node; node.prev = prev; }
            if(node.next != null) stack.push(node.next);
            if(node.child != null){ stack.push(node.child); node.child = null; }
            prev = node;
        }
        return head;
    }
}

