// This C implementation uses a simple stack array for DFS
struct Node* flatten(struct Node* head){
    if(!head) return NULL;
    struct Node* stack[1000]; int top=-1;
    stack[++top]=head;
    struct Node* prev=NULL;
    while(top>=0){
        struct Node* node=stack[top--];
        if(prev){ prev->next=node; node->prev=prev; }
        if(node->next) stack[++top]=node->next;
        if(node->child){ stack[++top]=node->child; node->child=NULL; }
        prev=node;
    }
    return head;
}

#include <stack>

class Solution {
public:
    Node* flatten(Node* head) {
        if (!head) return nullptr;
        std::stack<Node*> s;
        s.push(head);
        Node* prev = nullptr;
        while (!s.empty()) {
            Node* node = s.top();
            s.pop();
            if (prev) {
                prev->next = node;
                node->prev = prev;
            }
            if (node->next) s.push(node->next);
            if (node->child) {
                s.push(node->child);
                node->child = nullptr;
            }
            prev = node;
        }
        return head;
    }
};

class Solution {
    public TreeNode sortedListToBST(ListNode head) {
        if(head == null) return null;
        if(head.next == null) return new TreeNode(head.val);
        ListNode slow = head, fast = head, prev = null;
        while(fast != null && fast.next != null){ prev = slow; slow = slow.next; fast = fast.next.next; }
        prev.next = null;
        TreeNode root = new TreeNode(slow.val);
        root.left = sortedListToBST(head);
        root.right = sortedListToBST(slow.next);
        return root;
    }
}

#include <stdlib.h>

struct ListNode { int val; struct ListNode* next; };
struct TreeNode { int val; struct TreeNode* left; struct TreeNode* right; };

struct TreeNode* sortedListToBST(struct ListNode* head){
    if(!head) return NULL;
    if(!head->next){ struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode)); node->val = head->val; node->left = node->right = NULL; return node; }
    struct ListNode *slow=head, *fast=head, *prev=NULL;
    while(fast && fast->next){ prev=slow; slow=slow->next; fast=fast->next->next; }
    prev->next=NULL;
    struct TreeNode* root = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    root->val = slow->val;
    root->left = sortedListToBST(head);
    root->right = sortedListToBST(slow->next);
    return root;
}

class Solution {
public:
    TreeNode* sortedListToBST(ListNode* head) {
        if (!head) return nullptr;
        if (!head->next) return new TreeNode(head->val);
        ListNode *slow = head, *fast = head, *prev = nullptr;
        while (fast && fast->next) {
            prev = slow;
            slow = slow->next;
            fast = fast->next->next;
        }
        prev->next = nullptr;
        TreeNode* root = new TreeNode(slow->val);
        root->left = sortedListToBST(head);
        root->right = sortedListToBST(slow->next);
        return root;
    }
};

