class LRUCache {
    int cap;
    std::list<std::pair<int, int>> l;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> m;
public:
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        if (m.find(key) == m.end()) return -1;
        l.splice(l.begin(), l, m[key]);
        return m[key]->second;
    }
    void put(int key, int value) {
        if (m.find(key) != m.end()) {
            l.splice(l.begin(), l, m[key]);
            m[key]->second = value;
            return;
        }
        if (l.size() == cap) {
            m.erase(l.back().first);
            l.pop_back();
        }
        l.push_front({key, value});
        m[key] = l.begin();
    }
};

from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.min_freq = 0
        self.key_val = {}
        self.key_freq = {}
        self.freq_keys = defaultdict(OrderedDict)

    def update(self, key):
        freq = self.key_freq[key]
        val = self.key_val[key]
        del self.freq_keys[freq][key]
        if not self.freq_keys[freq] and freq == self.min_freq:
            self.min_freq +=1
        self.key_freq[key] +=1
        self.freq_keys[freq+1][key]=val

    def get(self, key):
        if key not in self.key_val: return -1
        self.update(key)
        return self.key_val[key]

    def put(self, key, value):
        if self.cap==0: return
        if key in self.key_val:
            self.key_val[key]=value
            self.update(key)
            return
        if len(self.key_val)>=self.cap:
            k,_=self.freq_keys[self.min_freq].popitem(last=False)
            del self.key_val[k]; del self.key_freq[k]
        self.key_val[key]=value
        self.key_freq[key]=1
        self.freq_keys[1][key]=value
        self.min_freq=1

import java.util.*;
class LFUCache {
    private int capacity, minFreq;
    private Map<Integer,Integer> keyVal;
    private Map<Integer,Integer> keyFreq;
    private Map<Integer,LinkedHashSet<Integer>> freqKeys;
    public LFUCache(int capacity){
        this.capacity=capacity; minFreq=0;
        keyVal=new HashMap<>(); keyFreq=new HashMap<>(); freqKeys=new HashMap<>();
    }
    public int get(int key){
        if(!keyVal.containsKey(key)) return -1;
        update(key); return keyVal.get(key);
    }
    public void put(int key,int value){
        if(capacity==0) return;
        if(keyVal.containsKey(key)){ keyVal.put(key,value); update(key); return; }
        if(keyVal.size()>=capacity){
            int evict = freqKeys.get(minFreq).iterator().next(); freqKeys.get(minFreq).remove(evict);
            keyVal.remove(evict); keyFreq.remove(evict);
        }
        keyVal.put(key,value); keyFreq.put(key,1);
        freqKeys.computeIfAbsent(1,k->new LinkedHashSet<>()).add(key);
        minFreq=1;
    }
    private void update(int key){
        int freq=keyFreq.get(key); freqKeys.get(freq).remove(key);
        if(freqKeys.get(freq).isEmpty() && freq==minFreq) minFreq++;
        keyFreq.put(key,freq+1);
        freqKeys.computeIfAbsent(freq+1,k->new LinkedHashSet<>()).add(key);
    }
}

