class LFUCache {
    int cap, minFreq;
    std::unordered_map<int, std::pair<int, int>> keyValFreq;
    std::unordered_map<int, std::list<int>> freqKeys;
    std::unordered_map<int, std::list<int>::iterator> keyIter;
public:
    LFUCache(int capacity) : cap(capacity), minFreq(0) {}
    int get(int key) {
        if (keyValFreq.find(key) == keyValFreq.end()) return -1;
        update(key); return keyValFreq[key].first;
    }
    void put(int key, int value) {
        if (cap <= 0) return;
        if (keyValFreq.count(key)) {
            keyValFreq[key].first = value;
            update(key); return;
        }
        if (keyValFreq.size() >= cap) {
            int evict = freqKeys[minFreq].back();
            freqKeys[minFreq].pop_back();
            keyValFreq.erase(evict); keyIter.erase(evict);
        }
        keyValFreq[key] = {value, 1};
        freqKeys[1].push_front(key);
        keyIter[key] = freqKeys[1].begin();
        minFreq = 1;
    }
    void update(int key) {
        int freq = keyValFreq[key].second;
        freqKeys[freq].erase(keyIter[key]);
        if (freqKeys[freq].empty() && freq == minFreq) minFreq++;
        keyValFreq[key].second++;
        freqKeys[freq + 1].push_front(key);
        keyIter[key] = freqKeys[freq + 1].begin();
    }
};

