#include <string>
#include <unordered_map>
#include <unordered_set>
#include <list>

class AllOne {
    struct Node { int count; std::unordered_set<std::string> keys; };
    std::list<Node> lst;
    std::unordered_map<std::string, std::list<Node>::iterator> m;
public:
    void inc(std::string key) {
        if (m.find(key) == m.end()) {
            if (lst.empty() || lst.front().count > 1) lst.push_front({1, {key}});
            else lst.front().keys.insert(key);
            m[key] = lst.begin();
        } else {
            auto it = m[key]; auto nextIt = std::next(it);
            if (nextIt == lst.end() || nextIt->count > it->count + 1) nextIt = lst.insert(nextIt, {it->count + 1, {key}});
            else nextIt->keys.insert(key);
            m[key] = nextIt; it->keys.erase(key);
            if (it->keys.empty()) lst.erase(it);
        }
    }
    void dec(std::string key) {
        auto it = m[key];
        if (it->count == 1) m.erase(key);
        else {
            auto prevIt = std::prev(it);
            if (it == lst.begin() || prevIt->count < it->count - 1) prevIt = lst.insert(it, {it->count - 1, {key}});
            else prevIt->keys.insert(key);
            m[key] = prevIt;
        }
        it->keys.erase(key); if (it->keys.empty()) lst.erase(it);
    }
    std::string getMaxKey() { return lst.empty() ? "" : *lst.back().keys.begin(); }
    std::string getMinKey() { return lst.empty() ? "" : *lst.front().keys.begin(); }
};
